<?php
namespace App\Models;
class RespuestaInstrumento extends ModeloOperativo { protected $table='respuestas_instrumento'; protected $primaryKey='cod_respuesta'; protected function casts(): array{return ['valor_logico'=>'boolean'];} protected static function booted(): void{static::saving(function(self $respuesta): void{$aplicacion=AplicacionInstrumento::query()->find($respuesta->cod_aplicacion);$pregunta=PreguntaInstrumento::query()->find($respuesta->cod_pregunta);if(! $aplicacion || ! $pregunta || $aplicacion->cod_instrumento!==$pregunta->cod_instrumento){throw \Illuminate\Validation\ValidationException::withMessages(['cod_pregunta'=>'La pregunta no pertenece al instrumento aplicado.']);}if($respuesta->cod_opcion && ! OpcionPregunta::query()->whereKey($respuesta->cod_opcion)->where('cod_pregunta',$respuesta->cod_pregunta)->exists()){throw \Illuminate\Validation\ValidationException::withMessages(['cod_opcion'=>'La opción no pertenece a la pregunta.']);}});} }
